/* Basic reset */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* Root variables for easy theming */
:root {
  --color-bg: #fff;
  --color-fg: #222;
  --color-muted: #666;
  --color-primary: #c00;
  --color-primary-hover: #a00;
  --color-border: #ddd;
  --color-focus: #0066cc;
  --font-sans: system-ui, sans-serif;
  --gap: 1rem;
}

/* Page defaults */
html {
  font-size: 100%; /* 16px base */
}
body {
  font-family: var(--font-sans);
  line-height: 1.5;
  background: var(--color-bg);
  color: var(--color-fg);
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--color-primary);
  color: #fff;
  padding: .5rem 1rem;
  z-index: 100;
  transition: top .2s;
}
.skip-link:focus {
  top: 0;
}

/* Header */
.site-header {
  background: var(--color-primary);
  color: #fff;
  padding: var(--gap);
}
.site-header h1 {
  font-size: 1.5rem;
  margin: 0;
}

/* Primary nav */
.primary-nav {
  display: flex;
  flex-wrap: wrap;
  gap: .5rem;
  margin-top: var(--gap);
}
.primary-nav a {
  color: #fff;
  text-decoration: none;
  padding: .25rem .5rem;
  border-radius: .25rem;
}
.primary-nav a:hover,
.primary-nav a:focus {
  background: rgba(255,255,255,.2);
  outline: none;
}

/* Hero */
.hero {
  text-align: center;
  padding: 2rem var(--gap);
  background: #fafafa;
}
.hero h2 {
  font-size: 2rem;
  margin-bottom: .5rem;
}
.hero p {
  color: var(--color-muted);
}

/* Content band */
.content-band {
  padding: var(--gap);
}
.section-title {
  font-size: 1.25rem;
  margin-bottom: .5rem;
  color: var(--color-primary);
}

/* Card grid */
.card-grid {
  display: grid;
  gap: var(--gap);
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
}
.card {
  border: 1px solid var(--color-border);
  border-radius: .25rem;
  overflow: hidden;
  background: #fff;
}
.card img {
  display: block;
  width: 100%;
  height: auto;
}
.card-body {
  padding: .5rem;
}
.card-title {
  font-size: 1rem;
  margin-bottom: .25rem;
}
.card-price {
  font-weight: bold;
  color: var(--color-primary);
}

/* Footer */
.site-footer {
  background: var(--color-fg);
  color: #fff;
  text-align: center;
  padding: var(--gap);
  font-size: .875rem;
}

/* Focus visible */
button:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 2px solid var(--color-focus);
  outline-offset: 2px;
}

/* Forms */
input,
select,
textarea {
  font: inherit;
  padding: .25rem .5rem;
  border: 1px solid var(--color-border);
  border-radius: .25rem;
  width: 100%;
  max-width: 300px;
}
input:focus,
select:focus,
textarea:focus {
  border-color: var(--color-focus);
  outline: none;
}

/* Error message */
.error-message {
  color: #c00;
  font-size: .875rem;
  margin-top: .25rem;
  display: none;
}

/* Hidden utility */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

/* Responsive: no horizontal scroll at 375px */
@media (max-width: 375px) {
  body {
    padding: 0 var(--gap);
  }
}

/* Prefers reduced motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}
